import { useState } from "react";

const Comptes = ({ users, sendEmail }) => {
  const [selectedUsers, setSelectedUsers] = useState([]);
  const [itemsPerPage, setItemsPerPage] = useState(5);
  const [currentPage, setCurrentPage] = useState(1);
  const [showPasswords, setShowPasswords] = useState({});

  const totalPages = Math.ceil(users.length / itemsPerPage);
  const startIndex = (currentPage - 1) * itemsPerPage;
  const currentUsers = users.slice(startIndex, startIndex + itemsPerPage);

  const handleSelectAll = (e) => {
    setSelectedUsers(e.target.checked ? currentUsers.map(user => user.id) : []);
  };

  const handleSelectUser = (userId) => {
    setSelectedUsers(prev => prev.includes(userId) ? prev.filter(id => id !== userId) : [...prev, userId]);
  };

  const togglePasswordVisibility = (userId) => {
    setShowPasswords(prev => ({ ...prev, [userId]: !prev[userId] }));
  };

  const sendEmailToSelected = async () => {
    let failedEmails = [];
    for (const userId of selectedUsers) {
      const user = users.find(user => user.id === userId);
      if (user) {
        try {
          await sendEmail(user.email, user.password);
        } catch (error) {
          failedEmails.push(user.email);
        }
      }
    }
    alert(failedEmails.length > 0 ? `Erreur lors de l'envoi des emails à : ${failedEmails.join(", ")}` : "Emails envoyés avec succès !");
  };

  return (
    <div className="p-4">
      <div className="mb-4 flex justify-between items-center">
        <label className="text-sm">Afficher : 
          <select className="ml-2 border p-1 rounded" value={itemsPerPage} onChange={(e) => {
            setItemsPerPage(Number(e.target.value));
            if (currentPage > Math.ceil(users.length / Number(e.target.value))) {
              setCurrentPage(Math.ceil(users.length / Number(e.target.value)));
            }
          }}>
            <option value="5">5</option>
            <option value="10">10</option>
            <option value="20">20</option>
          </select>
        </label>
        <button className="bg-blue-600 text-white px-4 py-2 rounded-lg" onClick={sendEmailToSelected}>Envoyer Email</button>
      </div>
      <table className="w-full border-collapse border border-gray-300">
        <thead>
          <tr className="bg-gray-100">
            <th className="p-2 border">
              <input type="checkbox" onChange={handleSelectAll} checked={currentUsers.length > 0 && currentUsers.every(user => selectedUsers.includes(user.id))} />
            </th>
            <th className="p-2 border">Nom</th>
            <th className="p-2 border">Email</th>
            <th className="p-2 border">Mot de passe</th>
          </tr>
        </thead>
        <tbody>
          {currentUsers.map(user => (
            <tr key={user.id} className="border">
              <td className="p-2 text-center">
                <input type="checkbox" checked={selectedUsers.includes(user.id)} onChange={() => handleSelectUser(user.id)} />
              </td>
              <td className="p-2">{user.name}</td>
              <td className="p-2">{user.email}</td>
              <td className="p-2">
                {showPasswords[user.id] ? user.password : '●●●●●'}
                <button onClick={() => togglePasswordVisibility(user.id)} className="ml-2 text-blue-600 hover:underline">
                  {showPasswords[user.id] ? "Cacher" : "Afficher"}
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <div className="mt-4 flex justify-center">
        {Array.from({ length: totalPages }, (_, index) => (
          <button key={index} onClick={() => setCurrentPage(index + 1)} className={`px-4 py-2 mx-1 text-sm rounded-lg transition duration-200 ${currentPage === index + 1 ? 'bg-blue-600 text-white font-bold' : 'bg-white text-blue-600 hover:bg-blue-100'}`}>
            {index + 1}
          </button>
        ))}
      </div>
    </div>
  );
};

export default Comptes;
